/** The committed M3 report is generated by the native Python binding. */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { loadPuckcore } from './loadWasm';

const report = JSON.parse(
  readFileSync(new URL('../../docs/validation/m3-validation.json', import.meta.url), 'utf8'),
) as {
  core_version: string;
  recipe: unknown;
  seed: number;
  samples: number;
  ensembles: Record<string, unknown>;
  taste: { undiluted: unknown; diluted_36g: unknown };
};

/** Avoid dumping the entire ensemble if a cross-platform regression occurs. */
function differences(actual: unknown, expected: unknown, path = ''): string[] {
  if (Object.is(actual, expected)) return [];
  if (
    typeof expected !== 'object' ||
    expected === null ||
    typeof actual !== 'object' ||
    actual === null
  ) {
    return [`${path}: ${String(actual)} != ${String(expected)}`];
  }
  const a = actual as Record<string, unknown>;
  const e = expected as Record<string, unknown>;
  if (Object.keys(a).length !== Object.keys(e).length) return [`${path}: key count differs`];
  return Object.keys(e)
    .flatMap((key) => differences(a[key], e[key], `${path}/${key}`))
    .slice(0, 10);
}

describe('M3 native / WebAssembly agreement', () => {
  const core = loadPuckcore();

  it('uses the report engine version', () => {
    expect(report.core_version).toBe(core.coreVersion());
  });

  it('replays every unknown-input scenario and band exactly', () => {
    const options = {
      samples: report.samples,
      seed: report.seed,
      groups: {
        grinder_psd: 'unknown',
        roast_age: 'unknown',
        composition: 'unknown',
        water: 'unknown',
      },
    };
    const actual = JSON.parse(
      core.simulateUncertainty(JSON.stringify(report.recipe), JSON.stringify(options)),
    ) as unknown;
    expect(differences(actual, report.ensembles.unknown)).toEqual([]);
  }, 120_000);

  it('matches native undiluted and diluted taste indices and their drivers', () => {
    const run = JSON.parse(core.simulateRecipe(JSON.stringify(report.recipe))) as {
      result: unknown;
      taste: unknown;
    };
    expect(differences(run.taste, report.taste.undiluted)).toEqual([]);
    const diluted = JSON.parse(
      core.estimateTaste(
        JSON.stringify(report.recipe),
        JSON.stringify(run.result),
        JSON.stringify({ dilution_water_g: 36 }),
      ),
    ) as unknown;
    expect(differences(diluted, report.taste.diluted_36g)).toEqual([]);
  }, 120_000);
});
